Extensions.ExtractScript:
param(
    [xml] $Document
);

foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
# Install driver packages matching the current hardware model from C:\Drivers\. $LogFile = 'C:\Windows\Setup\Scripts\Install-ModelDrivers.log' $DriversRoot = 'C:\Drivers'
function Write-Log { param([string]$Message) "$([datetime]::Now.ToString('[MM/dd/yyyy|HH:mm:ss]')) $Message" | Out-File -FilePath $LogFile -Append -Encoding UTF8 }
if (-not (Test-Path -LiteralPath $DriversRoot)) { Write-Log 'No C:\Drivers folder found; skipping.' return }
$Model = (Get-CimInstance -ClassName Win32_ComputerSystem).Model Write-Log "Model detected: $Model"
# Match a subfolder whose name is a substring of the full model string. $Match = Get-ChildItem -LiteralPath $DriversRoot -Directory | Where-Object { $Model -like "*$($_.Name)*" } | Select-Object -First 1
if (-not $Match) { Write-Log "No driver folder matched '$Model'; nothing to install." return }
Write-Log "Installing from: $($Match.FullName)"
# MSI packages first so they register their own INFs before pnputil runs. Get-ChildItem -LiteralPath $Match.FullName -Filter '*.msi' -Recurse | ForEach-Object { Write-Log " msiexec: $($_.Name)" $p = Start-Process -FilePath 'msiexec.exe' -ArgumentList "/i `"$($_.FullName)`" /quiet /norestart" -Wait -PassThru Write-Log " exit: $($p.ExitCode)" }
# Loose INF drivers not covered by an MSI. Get-ChildItem -LiteralPath $Match.FullName -Filter '*.inf' -Recurse | ForEach-Object { Write-Log " pnputil: $($_.Name)" $pnpOutput = pnputil.exe /add-driver $_.FullName /install | Out-String Write-Log $pnpOutput.Trim() }
Write-Log 'Done. Removing C:\Drivers.' Remove-Item -LiteralPath $DriversRoot -Recurse -Force -ErrorAction SilentlyContinue
